): Promise<{ analysis: SourceAnalysisV2; report: ValidationReport; receipt: MetaReceipt; authorizedPaths: string[] }> {
  const maxOutputTokens: number = resolveMaxTokens(opts.maxOutputTokens, KIT_CALL_MAX_OUTPUT_TOKENS);
